import type { ZwaveNodeData } from '../manager/zwave';
import type { ZwaveNodeOptions } from '../lib/ZwaveNode';
export type OnEventEvent = {
    args: ZwaveNodeData;
    return: void;
};
export type GetNodeEvent = {
    args: Record<string, unknown>;
    return: ZwaveNodeOptions;
};
export type SendCommandEvent = {
    args: {
        commandClassId: number;
        commandId: number;
        params?: Buffer;
        multiChannelNodeId?: number;
    };
    return: void;
};
export type CommandEvent = {
    args: {
        command: string;
        args: Record<string, unknown>;
        callback: boolean;
    };
    return: unknown;
};
export type HomeyZwaveEvents = {
    onEvent: OnEventEvent;
};
export type SDKZwaveEvents = {
    getNode: GetNodeEvent;
    sendCommand: SendCommandEvent;
    command: CommandEvent;
};
type BoundClient<TOmit extends string> = {
    emit: <T extends keyof SDKZwaveEvents>(event: T, data?: Omit<SDKZwaveEvents[T]['args'], TOmit>) => Promise<SDKZwaveEvents[T]['return']>;
};
export type NodeClient = BoundClient<'token'>;
export type CommandClassClient = BoundClient<'token' | 'commandClass' | 'multiChannelNodeId'>;
/**
 * The commands of a command class, added at runtime from the node's command list and named in
 * UPPER_SNAKE_CASE (e.g. `BASIC_SET`). Each sends that command to the node and resolves with its
 * response. The uppercase pattern keeps them from clashing with the class's own members.
 */
export type ZwaveCommands = {
    [command: Uppercase<string>]: (args?: Record<string, unknown>) => Promise<unknown>;
};
export {};
